#!/usr/bin/env python3
"""Categorize a batch's commits by numstat. Read-only on the repo."""
import subprocess, sys, os, re, json, collections

REPO = '/home/user/fortress'
def git(*args, text=True):
    return subprocess.run(['git', '-C', REPO] + list(args), capture_output=True, text=text, check=True).stdout

COORD = {
    'explorations/coordinator/FACTS.md', 'explorations/coordinator/POSITIONS.md',
    'explorations/coordinator/PLAN.md', 'explorations/coordinator/INDEX.md',
    'explorations/fortress-gap-ledger.md', 'explorations/microgpt-run-c-handover.md',
}
TESTDIRS = ('tests/', 'compiler_tests/', 'library_tests/', 'not_passing_yet/', 'not_working_compiler_tests/',
            'not_working_library_tests/', 'not_working_static_tests/', 'parser_tests/', 'linker_tests/',
            'other_compiler_tests/', 'compiler_regressions/', 'shelltests/', 'syntax_abstraction_tests/',
            'long_term_not_working/', 'obsolete_interpreter_tests/', 'test_library/')
CAPT = {'.txt', '.tsv', '.out', '.log', '.csv', '.json'}
PROBE = {'.fss', '.fsi', '.test'}
SCRIPT = {'.sh', '.py', '.js', '.java', '.scala', '.pl', '.awk', '.rb', '.bash', '.mjs', '.patch'}

def category(p):
    if p in COORD: return ('COORD', os.path.basename(p))
    if p.startswith('explorations/'):
        ext = os.path.splitext(p)[1]
        if ext == '.md': return ('RECORDS', 'REPORTS')
        if ext in CAPT: return ('RECORDS', 'CAPTURES')
        if ext in PROBE: return ('RECORDS', 'PROBES')
        if ext in SCRIPT: return ('RECORDS', 'SCRIPTS')
        return ('RECORDS', 'OTHER')
    if p.startswith('Library/') or p.startswith('ProjectFortress/LibraryBuiltin/'):
        return ('CODE', 'library')
    if p.startswith('ProjectFortress/src/'):
        if p.endswith('.java'): return ('CODE', 'java')
        if p.endswith('.scala'): return ('CODE', 'scala')
        return ('CODE', 'other-src')
    if p.startswith('ProjectFortress/astgen/') or os.path.basename(p) == 'build.xml':
        return ('CODE', 'build')
    if p.startswith('Specification/'):
        if p.endswith('.tex'): return ('SPEC', 'tex')
        if p == 'Specification/fortress.pdf': return ('SPEC', 'pdf')
        return ('SPEC', 'other')
    if p.startswith('SpecData/'): return ('SPECDATA', 'examples')
    if p.startswith('ProjectFortress/'):
        rest = p[len('ProjectFortress/'):]
        if rest.startswith(TESTDIRS): return ('TESTS', rest.split('/')[0])
        return ('OTHERTREE', rest.split('/')[0])
    return ('OTHERTREE', p.split('/')[0])

def commit_rows(c):
    out = git('show', '--numstat', '-M', '-z', '--format=', c)
    st = git('show', '--name-status', '-M', '-z', '--format=', c)
    # parse name-status
    toks = st.split('\0'); i = 0; stat = {}
    while i < len(toks):
        t = toks[i]
        if not t: i += 1; continue
        if t[0] in 'RC':
            stat[toks[i+2]] = (t[0], toks[i+1]); i += 3
        else:
            stat[toks[i+1]] = (t[0], None); i += 2
    toks = out.split('\0'); i = 0; rows = []
    while i < len(toks):
        t = toks[i]
        if not t.strip(): i += 1; continue
        t = t.lstrip('\n')
        a, d, p = t.split('\t', 2)
        if p == '':
            old, new = toks[i+1], toks[i+2]; i += 3
        else:
            old, new = None, p; i += 1
        s, o = stat.get(new, ('?', old))
        binary = (a == '-')
        rows.append(dict(commit=c, path=new, old=old or o, status=s, add=0 if binary else int(a),
                         dele=0 if binary else int(d), binary=binary))
    return rows

def blob_size(rev, path):
    try:
        return int(git('cat-file', '-s', f'{rev}:{path}').strip())
    except subprocess.CalledProcessError:
        return None

def blob_lines(rev, path):
    try:
        data = subprocess.run(['git', '-C', REPO, 'show', f'{rev}:{path}'], capture_output=True, check=True).stdout
        return data.count(b'\n')
    except subprocess.CalledProcessError:
        return None

if __name__ == '__main__':
    name = sys.argv[1]; commits = sys.argv[2:]
    rows = []
    for c in commits: rows += commit_rows(c)
    json.dump(rows, open(f'/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/characterize/batch-7-7R/{name}-rows.json', 'w'))
    agg = collections.defaultdict(lambda: [set(), 0, 0])
    for r in rows:
        k = category(r['path'])
        agg[k][0].add(r['path']); agg[k][1] += r['add']; agg[k][2] += r['dele']
    for k in sorted(agg):
        print(k, len(agg[k][0]), '+%d' % agg[k][1], '-%d' % agg[k][2])

